// n8n — Code « Recherche Ten'Up » (webhook GET /webhook/rebond-fft)
// Paramètres : nom + prenom, OU q (« Julien Dupont » / « Dupont Julien »), genre facultatif (H|F).
// Ten'Up ne trouve que le nom + prénom EXACTS (casse et accents ignorés) : on essaie
// les deux découpages possibles de q. Au plus 4 appels par recherche.
const API = 'https://tenup.fft.fr/api/back/public/v2/classements/recherche';
const UA = 'LeRebondNoyon/1.0 (+https://le-rebond.fr)';
const helpers = this.helpers;

async function tenup(corps) {
    try {
        return await helpers.httpRequest({
            method: 'POST', url: API, json: true, timeout: 15000,
            headers: { 'User-Agent': UA, Accept: 'application/json' },
            body: Object.assign({ pratique: 'PADEL' }, corps)
        });
    } catch (e) {
        // 400 = « recherche impossible avec ces paramètres » : personne de classé à ce nom.
        // Selon la version de n8n, le code HTTP n'est pas au même endroit (AxiosError, NodeApiError…).
        const code = Number(e.httpCode || e.statusCode || e.status
            || (e.response && (e.response.status || e.response.statusCode))
            || (e.cause && (e.cause.status || (e.cause.response && e.cause.response.status)))
            || (String(e.message).match(/status code (\d{3})/) || [])[1]);
        if (code === 400) return { joueurs: [] };
        throw e;
    }
}

const p = ($input.first().json.query) || {};
const propre = s => String(s || '').trim().replace(/\s+/g, ' ').slice(0, 60);
let paires = [];
if (p.nom && p.prenom) {
    paires.push([propre(p.nom), propre(p.prenom)]);
} else if (p.q) {
    const mots = propre(p.q).split(' ');
    if (mots.length >= 2) {
        paires.push([mots.slice(1).join(' '), mots[0]]);                      // « Julien Dupont »
        paires.push([mots.slice(0, -1).join(' '), mots[mots.length - 1]]);    // « Dupont Julien »
    }
}
paires = paires.filter((x, i, t) => x[0].length >= 2 && x[1].length >= 2
    && t.findIndex(y => y[0] === x[0] && y[1] === x[1]) === i);
const genres = (p.genre === 'H' || p.genre === 'F') ? [p.genre] : ['H', 'F'];

let mois = null;
const joueurs = [];
for (const [nom, prenom] of paires) {
    for (const sexe of genres) {
        const r = await tenup({ sexe, nom, prenom });
        if (r.referentiels && r.referentiels.datesClassement) mois = r.referentiels.datesClassement[0];
        (r.joueurs || [])
            .filter(j => j.utilisateurRecherche && j.nom)     // nom null = joueur anonyme sur Ten'Up
            .forEach(j => joueurs.push(Object.assign({}, j, { sexe })));
    }
    if (joueurs.length) break;
}

return [{ json: {
    mois,
    joueurs: joueurs.map(j => ({
        rang: j.classement, nom: j.nom, prenom: j.prenom, points: j.points, genre: j.sexe,
        club: j.club, ligue: j.ligue, comite: j.comite, id_crm: j.idCrm, mois
    })),
    brut: joueurs
} }];

// Mois du dernier classement publié (une seule requête, petite réponse).
const r = await this.helpers.httpRequest({
    method: 'POST', json: true, timeout: 15000,
    url: 'https://tenup.fft.fr/api/back/public/v2/classements/recherche',
    headers: { 'User-Agent': 'LeRebondNoyon/1.0 (+https://le-rebond.fr)', Accept: 'application/json' },
    body: { pratique: 'PADEL', sexe: 'F', page: 1, codeLigue: 56, codesComites: ['5660'], afficheReferentiels: true }
});
const mois = r.referentiels && r.referentiels.datesClassement && r.referentiels.datesClassement[0];
if (!mois) throw new Error('Mois du classement introuvable dans la réponse Ten\'Up');
return [{ json: { mois } }];

// n8n — Code « Vérifier sur Ten'Up » (tâche quotidienne, une exécution pour tout le lot)
// Entrée : les joueurs renvoyés par fft_joueurs_a_verifier(mois, limite).
// Pour chacun : recherche par identifiant FFT s'il est connu, sinon par nom + prénom.
//   1 classé trouvé  → 'classe'      (on retient son identifiant FFT)
//   plusieurs        → 'homonymes'   (à trancher dans l'admin, les candidats vont en cache)
//   aucun            → 'non_classe'
// Une requête toutes les 0,8 s, et arrêt à 230 s : le node Code est coupé à 300 s ;
// ce qui reste est repris le lendemain.
const API = 'https://tenup.fft.fr/api/back/public/v2/classements/recherche';
const UA = 'LeRebondNoyon/1.0 (+https://le-rebond.fr)';
const PAUSE_MS = 800, BUDGET_MS = 230000;
const helpers = this.helpers;
const pause = ms => new Promise(r => setTimeout(r, ms));

async function tenup(corps) {
    try {
        return await helpers.httpRequest({
            method: 'POST', url: API, json: true, timeout: 15000,
            headers: { 'User-Agent': UA, Accept: 'application/json' },
            body: Object.assign({ pratique: 'PADEL' }, corps)
        });
    } catch (e) {
        // Selon la version de n8n, le code HTTP n'est pas au même endroit (AxiosError, NodeApiError…).
        const code = Number(e.httpCode || e.statusCode || e.status
            || (e.response && (e.response.status || e.response.statusCode))
            || (e.cause && (e.cause.status || (e.cause.response && e.cause.response.status)))
            || (String(e.message).match(/status code (\d{3})/) || [])[1]);
        if (code === 400) return { joueurs: [] };
        throw e;
    }
}

const debut = Date.now();
const mois = $('Mois du classement').first().json.mois;
const resultats = [], lignes = [];
let interrompu = false;

for (const item of $input.all()) {
    if (Date.now() - debut > BUDGET_MS) { interrompu = true; break; }
    const j = item.json;
    const genres = (j.genre === 'H' || j.genre === 'F') ? [j.genre] : ['H', 'F'];
    let trouves = [];
    for (const sexe of genres) {
        const corps = j.fft_id_crm ? { sexe, idCrm: Number(j.fft_id_crm) } : { sexe, nom: j.nom, prenom: j.prenom };
        const r = await tenup(corps);
        await pause(PAUSE_MS);
        trouves = (r.joueurs || []).filter(x => x.utilisateurRecherche && x.nom).map(x => Object.assign({}, x, { sexe }));
        if (trouves.length) break;
    }
    lignes.push(...trouves);
    if (trouves.length === 1) {
        const t = trouves[0];
        resultats.push({ joueur_id: j.id, statut: 'classe', id_crm: t.idCrm, rang: t.classement,
                         points: t.points, genre: t.sexe, club: t.club });
    } else {
        resultats.push({ joueur_id: j.id, statut: trouves.length > 1 ? 'homonymes' : 'non_classe' });
    }
}

return [{ json: { mois, resultats, lignes, verifies: resultats.length, interrompu,
                  duree_s: Math.round((Date.now() - debut) / 1000) } }];
